    template <typename T> void fill(hoNDArray<T>* x, T val) {
        size_t N = x->get_number_of_elements();
        T* pX    = x->begin();

        long long n;
#pragma omp parallel for default(none) private(n) shared(N, pX, val) if (N > NumElementsUseThreading)
        for (n = 0; n < (long long)N; n++) {
            pX[n] = val;
        }
    }

