    template <typename T> void minAbsolute(const hoNDArray<T>& x, T& r, size_t& ind) {
        size_t N    = x.get_number_of_elements();
        const T* pX = x.begin();

        ind = 0;
        if (N == 0)
            return;

        long long n;

        typename realType<T>::Type v = abs(pX[0]);
        typename realType<T>::Type v2;

        ind = 0;
        for (n = 1; n < (long long)N; n++) {
            v2 = std::abs(pX[n]);
            if (v2 < v) {
                v   = v2;
                ind = n;
            }
        }

        r = pX[ind];
    }

