    template <class T> void minValue(const hoNDArray<T>& a, T& v) {
        typedef T ValueType;

        try {
            const ValueType* pA = a.begin();
            size_t n            = a.get_number_of_elements();
            v                   = pA[0];

            size_t ii;
            for (ii = 1; ii < n; ii++) {
                if (pA[ii] < v)
                    v = pA[ii];
            }
        } catch (...) {
            GADGET_THROW("Errors in minValue(const hoNDArray<T>& a, T& v) ... ");
        }
    }

